/* beast.merge_BST_SYNC_ADM_SYS_DPLY */ MERGE
BST_SYNC_TB_ADM_SYS_DPLY as_item
BST_SYNC_TB_AZURE_ADM_SYS_DPLY as_item
BST_SYNC_ADM_SYS_DPLY as_item
BST_SYNC_AZURE_ADM_SYS_DPLY as_item
USING ( SELECT #{sysId} AS SYS_ID , #{dplyDt} AS DPLY_DT , #{dplyType} AS DPLY_TYPE , #{sysNm} AS SYS_NM , #{sysCd} AS SYS_CD , #{apiLinkCd} AS API_LINK_CD , #{edptProt} AS EDPT_PROT , #{edptAtribUrl} AS EDPT_ATRIB_URL , #{edptAtribCerti} AS EDPT_ATRIB_CERTI , #{edptAtribCertiKey} AS EDPT_ATRIB_CERTI_KEY , #{edptAtribEcod} AS EDPT_ATRIB_ECOD , #{edptAtribAddr} AS EDPT_ATRIB_ADDR , #{edptAtribMinPool} AS EDPT_ATRIB_MIN_POOL , #{edptAtribMaxPool} AS EDPT_ATRIB_MAX_POOL , #{koaSysId} AS KOA_SYS_ID ) AS src ON (tar.SYS_ID = src.SYS_ID) WHEN MATCHED THEN UPDATE SET tar.UDATE = NOW() , tar.DPLY_DT = src.DPLY_DT , tar.DPLY_TYPE = src.DPLY_TYPE , tar.SYS_NM = src.SYS_NM , tar.SYS_CD = src.SYS_CD , tar.API_LINK_CD = src.API_LINK_CD , tar.EDPT_PROT = src.EDPT_PROT , tar.EDPT_ATRIB_URL = src.EDPT_ATRIB_URL , tar.EDPT_ATRIB_CERTI = src.EDPT_ATRIB_CERTI , tar.EDPT_ATRIB_CERTI_KEY = src.EDPT_ATRIB_CERTI_KEY , tar.EDPT_ATRIB_ECOD = src.EDPT_ATRIB_ECOD , tar.EDPT_ATRIB_ADDR = src.EDPT_ATRIB_ADDR , tar.EDPT_ATRIB_MIN_POOL = (CASE ISNUMERIC(src.EDPT_ATRIB_MIN_POOL) WHEN 1 THEN src.EDPT_ATRIB_MIN_POOL ELSE NULL END) , tar.EDPT_ATRIB_MAX_POOL = (CASE ISNUMERIC(src.EDPT_ATRIB_MAX_POOL) WHEN 1 THEN src.EDPT_ATRIB_MAX_POOL ELSE NULL END) , tar.KOA_SYS_ID = src.KOA_SYS_ID WHEN NOT MATCHED THEN INSERT ( DPLY_DT, DPLY_TYPE, SYS_ID, SYS_NM, SYS_CD, API_LINK_CD, EDPT_PROT, EDPT_ATRIB_URL, EDPT_ATRIB_CERTI, EDPT_ATRIB_CERTI_KEY, EDPT_ATRIB_ECOD, EDPT_ATRIB_ADDR, EDPT_ATRIB_MIN_POOL, EDPT_ATRIB_MAX_POOL, KOA_SYS_ID, UDATE, RDATE ) VALUES ( src.DPLY_DT, src.DPLY_TYPE, src.SYS_ID, src.SYS_NM, src.SYS_CD, src.API_LINK_CD, src.EDPT_PROT, src.EDPT_ATRIB_URL, src.EDPT_ATRIB_CERTI, src.EDPT_ATRIB_CERTI_KEY, src.EDPT_ATRIB_ECOD, src.EDPT_ATRIB_ADDR, src.EDPT_ATRIB_MIN_POOL, src.EDPT_ATRIB_MAX_POOL, src.KOA_SYS_ID, NOW(), NOW() );

/* beast.merge_BST_SYNC_ADM_API_DPLY */ MERGE
BST_SYNC_TB_ADM_API_DPLY AS tar
BST_SYNC_TB_AZURE_ADM_API_DPLY AS tar
BST_SYNC_ADM_API_DPLY AS tar
BST_SYNC_AZURE_ADM_API_DPLY AS tar
USING ( SELECT #{apiId} AS API_ID , #{dplyDt} AS DPLY_DT , #{dplyType} AS DPLY_TYPE , #{sysId} AS SYS_ID , #{ifNo} AS IF_NO , #{ver} AS VER , #{meth} AS METH , #{uriIn} AS URI_IN , #{uriOut} AS URI_OUT , #{reqHndlr} AS REQ_HNDLR , #{resHndlr} AS RES_HNDLR , #{errHndlr} AS ERR_HNDLR , #{timeOut} AS TIME_OUT , #{prnts} AS PRNTS , #{prntsApiId} AS PRNTS_API_ID , #{hndlrOptn} AS HNDLR_OPTN , #{mask} AS MASK , #{atribInFmt} AS ATRIB_IN_FMT , #{atribOutFmt} AS ATRIB_OUT_FMT , #{atribInComnParam} AS ATRIB_IN_COMN_PARAM , #{atribOutComnParam} AS ATRIB_OUT_COMN_PARAM , #{srcTag} AS SRC_TAG , #{srcKey} AS SRC_KEY , #{defApiNo} AS DEF_API_NO ) AS src ON (tar.API_ID = src.API_ID) WHEN MATCHED THEN UPDATE SET tar.UDATE = NOW() , tar.DPLY_DT = src.DPLY_DT , tar.DPLY_TYPE = src.DPLY_TYPE , tar.SYS_ID = src.SYS_ID , tar.IF_NO = src.IF_NO , tar.VER = src.VER , tar.METH = src.METH , tar.URI_IN = src.URI_IN , tar.URI_OUT = src.URI_OUT , tar.REQ_HNDLR = src.REQ_HNDLR , tar.RES_HNDLR = src.RES_HNDLR , tar.ERR_HNDLR = src.ERR_HNDLR , tar.TIME_OUT = (CASE ISNUMERIC(src.TIME_OUT) WHEN 1 THEN src.TIME_OUT ELSE NULL END) , tar.PRNTS = (CASE LOWER(src.PRNTS) WHEN 'true' THEN src.PRNTS WHEN 'false' THEN src.PRNTS ELSE NULL END) , tar.PRNTS_API_ID = src.PRNTS_API_ID , tar.HNDLR_OPTN = src.HNDLR_OPTN , tar.MASK = src.MASK , tar.ATRIB_IN_FMT = src.ATRIB_IN_FMT , tar.ATRIB_OUT_FMT = src.ATRIB_OUT_FMT , tar.ATRIB_IN_COMN_PARAM = src.ATRIB_IN_COMN_PARAM , tar.ATRIB_OUT_COMN_PARAM = src.ATRIB_OUT_COMN_PARAM , tar.SRC_TAG = src.SRC_TAG , tar.SRC_KEY = src.SRC_KEY , tar.DEF_API_NO = (CASE ISNUMERIC(src.DEF_API_NO) WHEN 1 THEN src.DEF_API_NO ELSE NULL END) WHEN NOT MATCHED THEN INSERT ( DPLY_DT, DPLY_TYPE, API_ID, SYS_ID, IF_NO, VER, METH, URI_IN, URI_OUT, REQ_HNDLR, RES_HNDLR, ERR_HNDLR, TIME_OUT, PRNTS, PRNTS_API_ID, HNDLR_OPTN, MASK, ATRIB_IN_FMT, ATRIB_OUT_FMT, ATRIB_IN_COMN_PARAM, ATRIB_OUT_COMN_PARAM, SRC_TAG, SRC_KEY, DEF_API_NO, UDATE, RDATE ) VALUES ( src.DPLY_DT, src.DPLY_TYPE, src.API_ID, src.SYS_ID, src.IF_NO, src.VER, src.METH, src.URI_IN, src.URI_OUT, src.REQ_HNDLR, src.RES_HNDLR, src.ERR_HNDLR, src.TIME_OUT, src.PRNTS, src.PRNTS_API_ID, src.HNDLR_OPTN, src.MASK, src.ATRIB_IN_FMT, src.ATRIB_OUT_FMT, src.ATRIB_IN_COMN_PARAM, src.ATRIB_OUT_COMN_PARAM, src.SRC_TAG, src.SRC_KEY, src.DEF_API_NO, NOW(), NOW() );

/* beast.merge_BST_SYNC_ADM_SVC_DPLY */ MERGE
BST_SYNC_TB_ADM_SVC_DPLY AS tar
BST_SYNC_TB_AZURE_ADM_SVC_DPLY AS tar
BST_SYNC_ADM_SVC_DPLY AS tar
BST_SYNC_AZURE_ADM_SVC_DPLY AS tar
USING ( SELECT #{svcId} AS SVC_ID , #{dplyDt} AS DPLY_DT , #{dplyType} AS DPLY_TYPE , #{svcNm} AS SVC_NM , #{userNm} AS USER_NM , #{pw} AS PW , #{slaSec} AS SLA_SEC , #{slaMin} AS SLA_MIN , #{slaHr} AS SLA_HR , #{slaDay} AS SLA_DAY , #{slaMon} AS SLA_MON , #{svcStDt} AS SVC_ST_DT , #{svcEndDt} AS SVC_END_DT , #{apiAut} AS API_AUT , #{ipAcesAutAlwdIp} AS IP_ACES_AUT_ALWD_IP , #{ipAcesAutBlckIp} AS IP_ACES_AUT_BLCK_IP , #{atribCpId} AS ATRIB_CP_ID , #{atribServiceId} AS ATRIB_SERVICE_ID , #{pwPlain} AS PW_PLAIN , #{srcTag} AS SRC_TAG , #{apiDomainAcesAut} AS API_DOMAIN_ACES_AUT , #{allowHttp} AS ALLOW_HTTP ) AS src ON (tar.SVC_ID = src.SVC_ID) WHEN MATCHED THEN UPDATE SET tar.UDATE = NOW() , tar.DPLY_DT = src.DPLY_DT , tar.DPLY_TYPE = src.DPLY_TYPE , tar.SVC_NM = src.SVC_NM , tar.USER_NM = src.USER_NM , tar.PW = src.PW , tar.SLA_SEC = (CASE ISNUMERIC(src.SLA_SEC) WHEN 1 THEN src.SLA_SEC ELSE NULL END) , tar.SLA_MIN = (CASE ISNUMERIC(src.SLA_MIN) WHEN 1 THEN src.SLA_MIN ELSE NULL END) , tar.SLA_HR = (CASE ISNUMERIC(src.SLA_HR) WHEN 1 THEN src.SLA_HR ELSE NULL END) , tar.SLA_DAY = (CASE ISNUMERIC(src.SLA_DAY) WHEN 1 THEN src.SLA_DAY ELSE NULL END) , tar.SLA_MON = (CASE ISNUMERIC(src.SLA_MON) WHEN 1 THEN src.SLA_MON ELSE NULL END) , tar.SVC_ST_DT = src.SVC_ST_DT , tar.SVC_END_DT = src.SVC_END_DT , tar.API_AUT = src.API_AUT , tar.IP_ACES_AUT_ALWD_IP = src.IP_ACES_AUT_ALWD_IP , tar.IP_ACES_AUT_BLCK_IP = src.IP_ACES_AUT_BLCK_IP , tar.ATRIB_CP_ID = src.ATRIB_CP_ID , tar.ATRIB_SERVICE_ID = src.ATRIB_SERVICE_ID , tar.PW_PLAIN = src.PW_PLAIN , tar.SRC_TAG = src.SRC_TAG , tar.API_DOMAIN_ACES_AUT = src.API_DOMAIN_ACES_AUT , tar.ALLOW_HTTP = src.ALLOW_HTTP WHEN NOT MATCHED THEN INSERT ( DPLY_DT, DPLY_TYPE, SVC_ID, SVC_NM, USER_NM, PW, SLA_SEC, SLA_MIN, SLA_HR, SLA_DAY, SLA_MON, SVC_ST_DT, SVC_END_DT, API_AUT, IP_ACES_AUT_ALWD_IP, IP_ACES_AUT_BLCK_IP, ATRIB_CP_ID, ATRIB_SERVICE_ID, PW_PLAIN, SRC_TAG, API_DOMAIN_ACES_AUT, ALLOW_HTTP, UDATE, RDATE ) VALUES ( src.DPLY_DT, src.DPLY_TYPE, src.SVC_ID, src.SVC_NM, src.USER_NM, src.PW, src.SLA_SEC, src.SLA_MIN, src.SLA_HR, src.SLA_DAY, src.SLA_MON, src.SVC_ST_DT, src.SVC_END_DT, src.API_AUT, src.IP_ACES_AUT_ALWD_IP, src.IP_ACES_AUT_BLCK_IP, src.ATRIB_CP_ID, src.ATRIB_SERVICE_ID, src.PW_PLAIN, src.SRC_TAG, src.API_DOMAIN_ACES_AUT, src.ALLOW_HTTP, NOW(), NOW() );

/* beast.merge_BST_SYNC_ADM_API_LINK_DATA */ MERGE
BST_SYNC_TB_ADM_API_LINK_DATA AS tar
BST_SYNC_TB_AZURE_ADM_API_LINK_DATA AS tar
BST_SYNC_ADM_API_LINK_DATA AS tar
BST_SYNC_AZURE_ADM_API_LINK_DATA AS tar
USING ( SELECT #{aldtType} AS ALDT_TYPE , #{aldtKey} AS ALDT_KEY , #{dplyDt} AS DPLY_DT , #{aldtValue} AS ALDT_VALUE , #{srcTag} AS SRC_TAG , #{srcKey} AS SRC_KEY , #{defApiNo} AS DEF_API_NO ) AS src ON (tar.ALDT_TYPE = src.ALDT_TYPE) AND (tar.ALDT_KEY = src.ALDT_KEY) WHEN MATCHED THEN UPDATE SET tar.UDATE = NOW() , tar.DPLY_DT = src.DPLY_DT , tar.ALDT_TYPE = src.ALDT_TYPE , tar.ALDT_VALUE = src.ALDT_VALUE , tar.SRC_TAG = src.SRC_TAG , tar.SRC_KEY = src.SRC_KEY , tar.DEF_API_NO = (CASE ISNUMERIC(src.DEF_API_NO) WHEN 1 THEN src.DEF_API_NO ELSE NULL END) WHEN NOT MATCHED THEN INSERT ( DPLY_DT, ALDT_TYPE, ALDT_KEY, ALDT_VALUE, SRC_TAG, SRC_KEY, DEF_API_NO, UDATE, RDATE ) VALUES ( src.DPLY_DT, src.ALDT_TYPE, src.ALDT_KEY, src.ALDT_VALUE, src.SRC_TAG, src.SRC_KEY, src.DEF_API_NO, NOW(), NOW() );

