/* beast.insert_BST_IF_EXEC_HIST */
INSERT INTO BST_IF_EXEC_HIST (
    LOG_DATE, LOG_TAG, LOG_MSG, REQ_URI, REQ_METHOD, REQ_HEADER, REQ_BODY, RES_STATUS_CODE, RES_HEADER, RES_BODY
)
VALUES (
    NOW(), #{logTag}, #{logMsg}, #{reqUri}, #{reqMethod}, #{reqHeader}, #{reqBody}, #{resStatusCode}, #{resHeader}, #{resBody}
)

