/* Beast_SQL.select_apitraffic_spclist */ SELECT SPC.API_SPC_NO AS API_SPC_NO , SPC.API_NM AS spc_API_NM , SYS.SYS_ID AS sys_SYS_ID , SYS.SYS_NM AS sys_SYS_NM FROM () AS SPC INNER JOIN KOA_TB_API_SYSTEM AS SYS ON (SYS.SYS_ID = SPC.SYS_ID) WHERE SPC.API_SPC_NO IN ( SELECT DEF.API_SPC_NO FROM KOA_TB_API_DEF AS DEF
) AND
